const norm = (s: string) => s.toLowerCase().replace(/[’']/g, "'");
export function matchFaq(q: string, limit = 2): { faq: Faq; score: number }[] {
  const ql = norm(q); const terms = ql.split(/[^a-z0-9$%'.]+/).filter(t => t.length > 3);
  return FAQ.map(f => {
    let score = 0;
    for (const m of f.match) if (ql.includes(norm(m))) score += m.includes(' ') ? 8 : 5;
    const hay = norm(`${f.q} ${f.answer}`); for (const t of terms) if (hay.includes(t)) score += 1;
    const qwords = norm(f.q).split(/\W+/).filter(w => w.length > 4); score += qwords.filter(w => ql.includes(w)).length * 2;
    return { faq: f, score };
  }).filter(x => x.score >= 8).sort((a, b) => b.score - a.score).slice(0, limit);
}
/** Map law topics and question text to in-app actions. */
export function actionsFor(question: string, lawIds: string[], intent?: string): ActionKey[] {
  const ql = question.toLowerCase(); const out = new Set<ActionKey>();
  const byTopic: Record<string, ActionKey[]> = { 'paga-cure': ['paga_cure', 'eec'], 'paga-2024': ['paga', 'steps'], 'paga-overview': ['paga'], settlements: ['settlement_packet', 'wage_letter'], 'meal-periods': ['meal_rest_policy', 'meal_waiver'], 'rest-periods': ['attestation', 'meal_rest_policy'], premiums: ['backpay'], 'regular-rate': ['payroll_memo'], exemptions: ['reclass'], contractors: ['reclass'], 'wage-statements': ['corrected_ws'], 'final-pay': ['waiting_time'], expenses: ['expense_policy'], rounding: ['timekeeping_policy'], 'hours-worked': ['timekeeping_policy'], arbitration: ['review_docs', 'scenarios'], 'records-requests': ['import'], 'minimum-wage': ['payroll_memo'], 'local-minimum-wage': ['payroll_memo'], 'split-reporting': ['payroll_memo'] };
  lawIds.forEach(id => (byTopic[id] || []).forEach(a => out.add(a)));
  if (/settle|release|pick ?up stix/.test(ql)) { out.add('settlement_packet'); out.add('settlement_valuation'); }
  if (/back ?pay|owe|owed|pay (them|employees)|make whole/.test(ql)) out.add('backpay');
  if (/what if|scenario|exclude|remediat/.test(ql)) out.add('scenarios');
  if (/board|management|summar|ceo|cfo/.test(ql)) out.add('board_brief');
  if (intent === 'findings' || intent === 'summary') { out.add('solutions'); out.add('backpay'); }
  if (intent === 'patterns') { out.add('detective'); out.add('training_memo'); }
  if (intent === 'workers') { out.add('backpay'); out.add('explorer'); }
  if (intent === 'scenario') { out.add('scenarios'); out.add('settlement_valuation'); }
  return [...out].slice(0, 5);
}
